#
# Version script for the interposer. Each symbol MUST sit in the same version
# node the real libamdhip64 assigns it, or a versioned reference from the
# application will not bind to our definition and the interposition silently
# does nothing. Tags come from `readelf --dyn-syms` on the shipped runtime.
#
# Under native handle identity a symbol we do NOT export is safe: the call
# reaches real HIP with a real HIP handle and simply runs unaccelerated. That
# is why this list shrank when the translating shims collapsed.

hip_4.2 {
    global:
        __hipRegisterFatBinary;
        __hipRegisterFunction;
        hipLaunchKernel;
        hipModuleGetFunction;
        hipModuleLaunchKernel;
        hipModuleLoadData;
        hipModuleLoadDataEx;
        hipModuleUnload;
};

hip_4.3 {
    global:
        hipGraphAddKernelNode;
        hipGraphAddMemcpyNode;
        hipGraphAddMemcpyNode1D;
        hipGraphAddMemsetNode;
        hipGraphCreate;
        hipGraphDestroy;
        hipGraphExecDestroy;
        hipGraphInstantiate;
        hipGraphLaunch;
        hipStreamBeginCapture;
        hipStreamEndCapture;
        hipStreamIsCapturing;
};

hip_4.4 {
    global:
        hipGraphAddDependencies;
        hipGraphAddEmptyNode;
        hipGraphExecKernelNodeSetParams;
        hipGraphKernelNodeSetParams;
        hipGraphMemcpyNodeSetParams;
        hipGraphMemsetNodeSetParams;
};

